  const paths = scene.map(item => {
    if (item.type === 'path') return new Path2D(item.d);
    const path = new Path2D();
    if (item.type === 'rect') path.rect(...item.rect);
    else {
      item.points.forEach(([x, y], i) => i ? path.lineTo(x, y) : path.moveTo(x, y));
      path.closePath();
    }
    return path;
  });

  function draw() {
    const density = Math.min(window.devicePixelRatio || 1, 3);
    canvas.width = Math.round(WIDTH * density);
    canvas.height = Math.round(HEIGHT * density);
    ctx.setTransform(canvas.width / WIDTH, 0, 0, canvas.height / HEIGHT, 0, 0);
    // The reference's blue gradient, with the same endpoints and stops.
    // Convert the gradient's nonuniform transform into its perpendicular projection.
    // Transforming only its endpoints would change the gradient direction in Canvas.
    const sx = 1.2751534;
    const sy = 0.78421936;
    const dx = 508.56625 - 38.034639;
    const dy = 1186.5303 - 715.99865;
    const vx = dx / sx;
    const vy = dy / sy;
    const factor = (dx * dx + dy * dy) / (vx * vx + vy * vy);
    const x = 38.034639 * sx;
    const y = 715.99865 * sy;
    const blue = ctx.createLinearGradient(x, y, x + vx * factor, y + vy * factor);
    blue.addColorStop(0, '#4abcf4');
    blue.addColorStop(0.5, '#51c5f8');
    blue.addColorStop(1, '#48baf1');

    scene.forEach((item, i) => {
      if (!state.right && (item.status || item.frame)) return;
      if (item.status && item.status !== state.right) return;
      ctx.save();
      for (const matrix of item.transforms || []) ctx.transform(...matrix);
      let fill = item.fill;
      let stroke = item.stroke;
      if (item.unit) {
        fill = state[item.unit] === 'blue' && item.unit === 'casper' ? blue : COLORS[state[item.unit]];
      }
      if (item.status) fill = STATUS[state.right];
      if (item.frame) stroke = STATUS[state.right];
      ctx.lineWidth = item.width;
      ctx.lineJoin = item.join;
      ctx.lineCap = item.cap;
      if (fill !== 'none') {
        ctx.fillStyle = fill;
        ctx.fill(paths[i], item.rule);
      }
      if (stroke !== 'none') {
        ctx.strokeStyle = stroke;
        ctx.stroke(paths[i]);
      }
      ctx.restore();
    });
  }
  draw();
  window.addEventListener('resize', draw);
